/**
 * Published tactical futures book.
 *
 * Generated by `python -m ace.tactical` from `ace/tactical/data/daily.csv`.
 * Pages do not import this module. `/api/tactical` returns the same object.
 */
import book from "./book.json";

export interface WindowResult {
  start: string;
  end: string;
  days: number;
  total_pnl: number;
  sharpe: number | null;
  max_drawdown: number;
  profit_factor: number | null;
  trade_count: number;
  days_with_pnl: number;
  cost_drag: number | null;
  gross_pnl: number;
  days_in_market: number;
}

export interface Comparison {
  sharpe_out_minus_in: number | null;
  pnl_in_sample: number;
  pnl_out_of_sample: number;
  max_drawdown_in_sample: number;
  max_drawdown_out_of_sample: number;
}

export interface AssetResult {
  available: boolean;
  reason?: string;
  in_sample?: WindowResult;
  out_of_sample?: WindowResult;
  comparison?: Comparison;
  equity_month_end?: { date: string; equity: number }[];
  last_target?: { date: string | null; contracts: number | null };
  position_on_last_session?: number;
}

export interface BookResult {
  legs: string[];
  note: string;
  in_sample: WindowResult;
  out_of_sample: WindowResult;
  comparison: Comparison;
  equity_month_end: { date: string; equity: number }[];
}

export interface TacticalModel {
  summary: string;
  assets: Record<string, AssetResult>;
  book: BookResult;
}

export interface TacticalLayers {
  core_model: string;
  selection_rule: string;
  candidates: string[];
  recommended: string;
  stack_chosen_on_test: boolean;
  parameters_fit_on_test: boolean;
  stacks: Record<
    string,
    {
      summary: string;
      beats_core: boolean;
      incremental_oos_pnl: number;
      assets: Record<string, AssetResult>;
      book: BookResult;
      hit_rate?: { calls: number; decided: number; hits: number; flats: number; hit_rate: number | null };
    }
  >;
}

export interface TacticalBook {
  schema: "tactical-book-v2";
  generated_at: string;
  as_of: string;
  tuned_on_test: boolean;
  windows: {
    train: { start: string; end: string; role: string };
    test: { start: string; end: string; role: string };
  };
  parameters: Record<string, unknown>;
  contracts: Record<string, { name: string; multiplier: number; cost_per_side: number; yahoo: string }>;
  data: {
    prices: string;
    real_yield: string;
    cl_2020_04_20_dollar_change: number | null;
    cl_2020_04_21_dollar_change: number | null;
  };
  citations: { id: string; short: string; cite: string; used_for: string }[];
  models: Record<string, TacticalModel>;
  layers: TacticalLayers;
}

export const tacticalBook = book as TacticalBook;

/** The precomputed book. Safe to call from a server function. Not used by a page. */
export function readTacticalBook(): TacticalBook {
  return tacticalBook;
}
